#include <iostream>
inline void dynamicsCheck(bool ok,const char* message){if(!ok){std::cerr<<"FAIL DYNAMICS: "<<message<<'\n';std::exit(1);}}
template<class Processor>int stockDynamicsHost(const char* path,const char* preview){juce::ScopedJuceInitialiser_GUI gui;juce::AudioPluginFormatManager formats;formats.addDefaultFormats();juce::OwnedArray<juce::PluginDescription> found;formats.getFormat(0)->findAllTypesForFile(found,juce::String::fromUTF8(path));dynamicsCheck(found.size()==1,"VST3 discovery");juce::String error;auto plugin=formats.createPluginInstance(*found[0],48000,256,error);dynamicsCheck(plugin!=nullptr,"VST3 instantiate");dynamicsCheck(plugin->getLatencySamples()==0,"zero latency");auto* parameter=plugin->getParameters()[0];parameter->setValueNotifyingHost(.7f);juce::MemoryBlock state;plugin->getStateInformation(state);parameter->setValueNotifyingHost(.2f);plugin->setStateInformation(state.getData(),int(state.getSize()));dynamicsCheck(std::abs(parameter->getValue()-.7f)<.001,"state restore");if(plugin->getName().contains("Plate")||plugin->getName().contains("Digital Delay")){dynamicsCheck(plugin->getTailLengthSeconds()>0,"time effect reports tail");plugin->prepareToPlay(48000,256);juce::AudioBuffer<float> audio(2,256);juce::MidiBuffer midi;double tail=0;for(int block=0;block<600;++block){audio.clear();if(block==0)audio.setSample(0,0,1);plugin->processBlock(audio,midi);for(int c=0;c<2;++c)for(int n=0;n<256;++n){float value=audio.getSample(c,n);dynamicsCheck(std::isfinite(value),"actual VST3 audio finite");if(block>0)tail+=value*value;}}dynamicsCheck(tail>1.e-8,"actual VST3 produces audible tail");plugin->releaseResources();}Processor native;native.prepareToPlay(48000,256);std::unique_ptr<juce::AudioProcessorEditor> editor(native.createEditorIfNeeded());editor->setVisible(true);juce::Image image(juce::Image::ARGB,editor->getWidth(),editor->getHeight(),true);{juce::Graphics g(image);editor->paintEntireComponent(g,true);}juce::FileOutputStream stream(juce::File(juce::String::fromUTF8(preview)));stream.setPosition(0);juce::PNGImageFormat png;dynamicsCheck(png.writeImageToStream(image,stream),"editor render");stream.truncate();return 0;}
inline int runLimiterTests(const char* path,const char* preview){using namespace TracksmithLimiter;for(double rate:{8000.,44100.,48000.,96000.,192000.}){Engine e;e.prepare(rate);Settings s;float l[256]{},r[256]{};float* ch[]{l,r};for(int b=0;b<200;++b){s.drive=float(b%25);s.ceiling=-float(b%24);for(int n=0;n<256;++n){l[n]=float(3*std::sin((b*256+n)*.7));r[n]=l[n]*.5f;}e.process(ch,2,256,s);float ceiling=std::pow(10.f,s.ceiling/20);for(int n=0;n<256;++n){dynamicsCheck(std::isfinite(l[n])&&std::abs(l[n])<=ceiling+1.e-6f,"sample ceiling survives automation");dynamicsCheck(std::abs(r[n]-l[n]*.5f)<1.e-6f,"stereo linked");}}
 s.bypass=true;for(int b=0;b<20;++b){std::fill_n(l,256,.5f);std::fill_n(r,256,0);e.process(ch,2,256,s);}dynamicsCheck(std::abs(l[255]-.5f)<1.e-6f,"bypass unity");dynamicsCheck(r[255]==0,"no crosstalk");}
 std::cout<<"PASS: limiter ceiling under drive/ceiling changes, stereo link, bypass, no crosstalk and 5 sample rates\n";return stockDynamicsHost<LimiterProcessor>(path,preview);}
inline int runDeesserTests(const char* path,const char* preview){using namespace TracksmithDeesser;auto measure=[](double frequency,float amplitude,bool automatic){Engine e;e.prepare(48000);Settings s;s.automatic=automatic;s.threshold=-30;float data[256]{};float* ch[]{data};double inputEnergy=0,outputEnergy=0;for(int b=0;b<300;++b){for(int n=0;n<256;++n){data[n]=amplitude*float(std::sin(2*TracksmithEq::pi*frequency*(b*256+n)/48000));if(b>250)inputEnergy+=data[n]*data[n];}e.process(ch,1,256,s);if(b>250)for(float value:data)outputEnergy+=value*value;}return 10*std::log10(outputEnergy/inputEnergy);};double high=measure(6000,.1f,true),low=measure(200,.1f,true);dynamicsCheck(high<-5,"sibilance band reduced");dynamicsCheck(std::abs(low)<.1,"low voice band retained");dynamicsCheck(std::abs(high-measure(6000,.01f,true))<.1,"auto threshold tracks input level");dynamicsCheck(measure(6000,.1f,false)<-5,"manual threshold reduction");
 for(double rate:{8000.,44100.,48000.,96000.,192000.}){Engine e;e.prepare(rate);Settings s;float l[256]{},r[256]{};float* ch[]{l,r};for(int b=0;b<100;++b){s.frequency=float(2000+(b%11)*1000);s.listen=b%2==1;s.bypass=b%3==1;for(int n=0;n<256;++n){l[n]=.1f*float(std::sin((b*256+n)*.5));r[n]=l[n]*.5f;}e.process(ch,2,256,s);for(int n=0;n<256;++n){dynamicsCheck(std::isfinite(l[n]),"deesser finite automation");dynamicsCheck(std::abs(r[n]-l[n]*.5f)<1.e-6f,"deesser stereo link");}}s.bypass=true;for(int b=0;b<20;++b){std::fill_n(l,256,.1f);std::fill_n(r,256,0);e.process(ch,2,256,s);}dynamicsCheck(std::abs(l[255]-.1f)<1.e-6f,"deesser bypass unity");}
 std::cout<<"PASS: deesser band selectivity, manual/auto threshold, input-level invariance, stereo linking, bypass, finite parameter changes and 5 sample rates\n";return stockDynamicsHost<DeesserProcessor>(path,preview);}
